begin;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,is_anonymous,raw_user_meta_data) values('311d0000-0000-4000-8000-000000000001',false,'{}');
insert into public.media_preferences(user_id,source_type,media_id,preference_state,source_event_id,source_event_at) values('311d0000-0000-4000-8000-000000000001','youtube','mbtestsource','liked','mb-like',now());
create function pg_temp.enqueue() returns jsonb language plpgsql as $$ declare r jsonb;begin execute 'select public.queue_musicbrainz_reference($1,$2,$3)' into r using '311d0000-0000-4000-8000-000000000001'::uuid,'mbtestsource','311d0000-0000-4000-8000-000000000011'::uuid;return r;exception when undefined_function then return null;end $$;
create function pg_temp.claim() returns jsonb language plpgsql as $$ declare r jsonb;begin execute 'select public.claim_musicbrainz_lookup()' into r;return r;exception when undefined_function then return null;end $$;
set local role service_role;
select is(pg_temp.enqueue()->>'status','pending','explicit owner reference queues without provider wait');
create temporary table claim as select pg_temp.claim() value;
select is((select value->>'mbid' from claim),'311d0000-0000-4000-8000-000000000011','worker receives only requested recording identity');
select is(pg_temp.claim(),'{}'::jsonb,'inflight lease excludes concurrent provider request');
select throws_ok($$select public.complete_musicbrainz_lookup((select(value->>'token')::uuid from claim),'311d0000-0000-4000-8000-000000000011','{"status":"ready","core":{"mbid":"311d0000-0000-4000-8000-000000000011","title":12,"artistCredit":"Artist","disambiguation":"","lengthMs":null}}')$$,'22023',null,'numeric title cannot be coerced into core identity');
select is(public.complete_musicbrainz_lookup('311d0000-0000-4000-8000-000000000099','311d0000-0000-4000-8000-000000000011','{"status":"not_found"}'),false,'foreign lease completion is fenced');
select is(public.complete_musicbrainz_lookup((select (value->>'token')::uuid from claim),'311d0000-0000-4000-8000-000000000011','{"status":"ready","core":{"mbid":"311d0000-0000-4000-8000-000000000011","title":"Test reference","artistCredit":"Fixture artist","disambiguation":"studio","lengthMs":123456}}'),true,'validated core fields complete the job');
select is(pg_temp.claim(),'{}'::jsonb,'completion cooldown prevents immediate next call');
create temporary table review as select public.read_musicbrainz_review('311d0000-0000-4000-8000-000000000001','mbtestsource') value;
select is((select value->>'status' from review),'ready','fresh lookup is reviewable');
select throws_ok($$select public.confirm_musicbrainz_reference('311d0000-0000-4000-8000-000000000001','mbtestsource',(select(value->>'selectionId')::uuid from review),0,'311d0000-0000-4000-8000-000000000077',true,(select(value->>'fetchedAt')::timestamptz-interval '1 second' from review))$$,'40001',null,'still-fresh but different reviewed snapshot cannot confirm');
select throws_ok($$select public.confirm_musicbrainz_reference('311d0000-0000-4000-8000-000000000001','mbtestsource',(select(value->>'selectionId')::uuid from review),0,'311d0000-0000-4000-8000-000000000021',false,(select(value->>'fetchedAt')::timestamptz from review))$$,'22023',null,'lookup does not replace explicit exact-version confirmation');
select is((public.confirm_musicbrainz_reference('311d0000-0000-4000-8000-000000000001','mbtestsource',(select(value->>'selectionId')::uuid from review),0,'311d0000-0000-4000-8000-000000000021',true,(select(value->>'fetchedAt')::timestamptz from review))->>'revision')::int,1,'confirmed private relationship is saved');
select is((public.confirm_musicbrainz_reference('311d0000-0000-4000-8000-000000000001','mbtestsource',(select(value->>'selectionId')::uuid from review),0,'311d0000-0000-4000-8000-000000000021',true,(select(value->>'fetchedAt')::timestamptz from review))->>'revision')::int,1,'confirmation retry is idempotent');
select throws_ok($$select public.confirm_musicbrainz_reference('311d0000-0000-4000-8000-000000000001','mbtestsource',(select(value->>'selectionId')::uuid from review),0,'311d0000-0000-4000-8000-000000000022',true,(select(value->>'fetchedAt')::timestamptz from review))$$,'40001',null,'stale confirmation cannot overwrite link');
select throws_ok($$select public.queue_musicbrainz_reference('311d0000-0000-4000-8000-000000000001','unknownsource','311d0000-0000-4000-8000-000000000011')$$,'42501',null,'arbitrary source cannot request lookup');
reset role;
update private.musicbrainz_jobs set expires_at=now()-interval '1 second';
set local role service_role;
select throws_ok($$select public.confirm_musicbrainz_reference('311d0000-0000-4000-8000-000000000001','mbtestsource',(select(value->>'selectionId')::uuid from review),1,'311d0000-0000-4000-8000-000000000023',true,(select(value->>'fetchedAt')::timestamptz from review))$$,'40001',null,'expired evidence cannot confirm');
select is(public.read_musicbrainz_review('311d0000-0000-4000-8000-000000000001','mbtestsource')->'core','null'::jsonb,'expired provider display data is not exposed');
reset role;
select ok(not has_function_privilege('authenticated','public.queue_musicbrainz_reference(uuid,text,uuid)','execute'),'browser cannot bypass verified account route');
select ok(not has_table_privilege('anon','private.musicbrainz_selections','select'),'private selections cannot be enumerated');
update private.musicbrainz_jobs set status='pending',attempts=3,lease_until=now()-interval '1 minute',requested_at=now();
select is(public.read_musicbrainz_review('311d0000-0000-4000-8000-000000000001','mbtestsource')->>'status','invalid','third-attempt worker crash does not remain pending');
update private.musicbrainz_jobs set status='not_found',attempts=1,requested_at=now()-interval '2 days';
select is(pg_temp.enqueue()->>'status','pending','explicit retry refreshes old terminal result after cooldown');
update private.musicbrainz_rate set used=100,day=(now() at time zone 'UTC')::date,next_at=now()-interval '1 minute',lease_until=null,token=null;
select is(pg_temp.claim(),'{}'::jsonb,'hard daily budget forbids another provider claim');
select * from finish();
rollback;
